{
  "items": [
    {
      "name": "Commute.add_pow'",
      "module_name": "Mathlib.Data.Nat.Choose.Sum",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {x y : R},\n  Commute x y → ∀ (n : ℕ), (x + y) ^ n = ∑ m ∈ Finset.antidiagonal n, n.choose m.1 • (x ^ m.1 * y ^ m.2)"
    },
    {
      "name": "Commute.add_pow",
      "module_name": "Mathlib.Data.Nat.Choose.Sum",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {x y : R},\n  Commute x y → ∀ (n : ℕ), (x + y) ^ n = ∑ m ∈ Finset.range (n + 1), x ^ m * y ^ (n - m) * ↑(n.choose m)"
    },
    {
      "name": "Ring.add_choose_eq",
      "module_name": "Mathlib.RingTheory.Binomial",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Ring R] [inst_1 : BinomialRing R] {r s : R} (k : ℕ),\n  Commute r s → Ring.choose (r + s) k = ∑ ij ∈ Finset.antidiagonal k, Ring.choose r ij.1 * Ring.choose s ij.2"
    },
    {
      "name": "add_pow",
      "module_name": "Mathlib.Data.Nat.Choose.Sum",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommSemiring R] (x y : R) (n : ℕ),\n  (x + y) ^ n = ∑ m ∈ Finset.range (n + 1), x ^ m * y ^ (n - m) * ↑(n.choose m)"
    },
    {
      "name": "Commute.exists_add_pow_prime_pow_eq",
      "module_name": "Mathlib.Algebra.CharP.Lemmas",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {p : ℕ},\n  Nat.Prime p → ∀ {x y : R}, Commute x y → ∀ (n : ℕ), ∃ r, (x + y) ^ p ^ n = x ^ p ^ n + y ^ p ^ n + ↑p * x * y * r"
    },
    {
      "name": "sub_pow",
      "module_name": "Mathlib.Data.Nat.Choose.Sum",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (x y : R) (n : ℕ),\n  (x - y) ^ n = ∑ m ∈ Finset.range (n + 1), (-1) ^ (m + n) * x ^ m * y ^ (n - m) * ↑(n.choose m)"
    },
    {
      "name": "Fintype.sum_pow_mul_eq_add_pow",
      "module_name": "Mathlib.Algebra.BigOperators.Ring.Finset",
      "kind": "theorem",
      "type": "∀ {R : Type u_4} [inst : CommSemiring R] (ι : Type u_5) [inst_1 : Fintype ι] (a b : R),\n  ∑ s, a ^ s.card * b ^ (Fintype.card ι - s.card) = (a + b) ^ Fintype.card ι"
    }
  ]
}
